struct ProductPhotoPicker: View {
    @Binding var selection: PhotosPickerItem?
    let imageData: Data?
    let isLoading: Bool
    let error: ProductPhotoError?
    let loader: ProductPhotoLoader
    let remove: () -> Void

    @State private var preview: UIImage?

actor ProductPhotoLoader {
    func load(using read: @Sendable () async throws -> Data?) async -> Result<Data, ProductPhotoError> {
        do {
            try Task.checkCancellation()
            let data = try await read()
            try Task.checkCancellation()

            guard let data else {
                return .failure(.unavailable)
            }

            guard !data.isEmpty, UIImage(data: data) != nil else {
                return .failure(.invalidImage)
            }

            return .success(data)

func load(using read: @Sendable () async throws -> Data?) async -> Result<Data, ProductPhotoError> {
    do {
        try Task.checkCancellation()
        let data = try await read()
        try Task.checkCancellation()

        guard let data else {
            return .failure(.unavailable)
        }

        guard !data.isEmpty, UIImage(data: data) != nil else {
            return .failure(.invalidImage)
        }

        return .success(data)
    } catch is CancellationError {
        return .failure(.cancelled)
    } catch {
        return .failure(.loading(error))

private func loadPhoto(_ item: PhotosPickerItem) {
    photoTask?.cancel()
    let requestID = state.photo.beginLoading()
    // 同じ写真を選び直した場合も、もう一度読み込めるようにする。
    selectedPhoto = nil

    photoTask = Task {
        let result = await photoLoader.load {
            try await item.loadTransferable(type: Data.self)
        }

        guard !Task.isCancelled, state.photo.requestID == requestID else {
            return
        }

        state.photo.complete(result, request: requestID)
        photoTask = nil

private enum Change {
    case unchanged
    case replaced(Data)
    case removed
}

private var change = Change.unchanged
private(set) var requestID: UUID?
private(set) var error: ProductPhotoError?

var isLoading: Bool {
    requestID != nil
}

func image(original: Data?) -> Data? {
    switch change {
    case .unchanged:
        return original
    case .replaced(let data):
        return data
    case .removed:
        return nil

private func persist(using actions: ProductActions) -> Result<UUID, ProductActions.ActionError> {
    guard let product else {
        return actions.create(from: draft, image: image).map { $0.id }
    }

    guard !product.isDeleted, product.modelContext != nil else {
        return .failure(.productNotInContext)
    }

    // 写真を操作していないときだけ、保存直前の画像を引き継ぐ。
    let productID = product.id
    return actions.update(product, from: draft, image: image).map { productID }

@Test func loadingValidImageAllowsAdditionAndReplacement() async throws {
    let data = try Self.imageData()
    let loader = ProductPhotoLoader()
    var state = ProductPhotoState()
    let request = state.beginLoading()

    #expect(state.isLoading)
    let result = await loader.load { data }
    state.complete(result, request: request)

    #expect(try result.get() == data)
    #expect(state.image(original: nil) == data)
    #expect(state.image(original: Data([1])) == data)
    #expect(!state.isLoading)
    #expect(state.error == nil)
    #expect(await loader.preview(for: data) != nil)
}

func missingOrInvalidImagePreservesPhoto(_ data: Data?) async throws {
    let original = try Self.imageData()
    let loader = ProductPhotoLoader()
    var state = ProductPhotoState()
    let request = state.beginLoading()

    let result = await loader.load { data }
    state.complete(result, request: request)

    guard case .failure = result else {
        Issue.record("読み込めない画像を成功扱いした")
        return
    }
    #expect(state.image(original: original) == original)
    #expect(state.error?.message != nil)
    #expect(!state.isLoading)
}

@Test func readFailureRetainsUnderlyingErrorAndRetryClearsIt() async throws {
    let data = try Self.imageData()
    let loader = ProductPhotoLoader()
    var state = ProductPhotoState()
    let request = state.beginLoading()
    let failure = await loader.load { throw ReadError.unavailable }
    state.complete(failure, request: request)

    guard case .loading(let underlying) = state.error else {
        Issue.record("元の読み込みエラーを保持しなかった")
        return
    }
    #expect(underlying as? ReadError == .unavailable)
    #expect(state.image(original: data) == data)

    let retry = state.beginLoading()
    state.complete(await loader.load { data }, request: retry)

    #expect(state.image(original: nil) == data)
    #expect(state.error == nil)
    #expect(!state.isLoading)
}

func olderCompletionCannotOverwriteNewerSelection(_ oldFails: Bool) throws {
    let data = try Self.imageData()
    var state = ProductPhotoState()
    let first = state.beginLoading()
    let second = state.beginLoading()
    let oldResult: Result<Data, ProductPhotoError> = oldFails ? .failure(.unavailable) : .success(Data([1]))

    state.complete(oldResult, request: first)
    #expect(state.isLoading)
    #expect(state.requestID == second)
    #expect(state.image(original: nil) == nil)
    #expect(state.error == nil)

    state.complete(.success(data), request: second)
    state.complete(oldResult, request: first)

    #expect(state.image(original: nil) == data)
    #expect(!state.isLoading)
    #expect(state.error == nil)
}

@Test func removingPhotoInvalidatesPendingResultAndClearsError() throws {
    let data = try Self.imageData()
    var state = ProductPhotoState()
    let failure = state.beginLoading()
    state.complete(.failure(.unavailable), request: failure)
    state.remove()
    #expect(state.error == nil)

    let pending = state.beginLoading()
    state.remove()
    state.complete(.success(data), request: pending)

    #expect(state.image(original: data) == nil)
    #expect(!state.isLoading)
    #expect(state.error == nil)
}

@Test func selectedPhotoIsSavedWithNewProductOnlyAfterSaving() throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    var state = ProductFormState()
    state.draft = ProductDraft(name: "写真付き商品", type: "しょうゆ")
    let image = try ProductPhotoPickerTests.imageData()
    let request = state.photo.beginLoading()
    state.photo.complete(.success(image), request: request)

    #expect(!context.hasChanges)
    #expect(try ModelContext(container).fetchCount(FetchDescriptor<Product>()) == 0)
    #expect(state.image == image)

    let id = try state.save(using: ProductActions(context: context)) { _ in }.get()

    let saved = try #require(ModelContext(container).fetch(FetchDescriptor<Product>()).first)
    #expect(saved.id == id)
    #expect(saved.image == image)
    #expect(try ModelContext(container).fetchCount(FetchDescriptor<Item>()) == 0)
    #expect(ProductFormState(product: saved).image == image)
}

@Test func photoReadFailurePreservesAllDraftFieldsAndSavedImage() throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    let product = try makeSavedProduct(in: context)
    var state = ProductFormState(product: product)
    state.draft = ProductDraft(
        name: " 編集中 ", type: " みそ ", priceYen: "398", calories: "10.25", protein: "2.5", fat: "1.23",
        sugar: "4.56", carbohydrates: "8.5", nutrientBasisAmount: "100", nutrientBasisUnit: "g"
    )
    let request = state.photo.beginLoading()

    state.photo.complete(.failure(.loading(StoreError.unavailable)), request: request)

    #expect(state.draft.name == " 編集中 ")
    #expect(state.draft.type == " みそ ")
    #expect(state.draft.priceYen == "398")
    #expect(state.draft.calories == "10.25")
    #expect(state.draft.protein == "2.5")
    #expect(state.draft.fat == "1.23")
    #expect(state.draft.sugar == "4.56")
    #expect(state.draft.carbohydrates == "8.5")
    #expect(state.draft.nutrientBasisAmount == "100")
    #expect(state.draft.nutrientBasisUnit == "g")
    #expect(state.image == Data([1, 2, 3]))
    #expect(state.photo.error?.message != nil)
    #expect(!context.hasChanges)
    #expect(state.savedProductID == nil)
    expectOptionalValues(product)

    try state.save(using: ProductActions(context: context)) { _ in }.get()

    let saved = try #require(ModelContext(container).fetch(FetchDescriptor<Product>()).first)
    #expect(saved.image == Data([1, 2, 3]))
    #expect(saved.name == "編集中")
}

func photoSaveFailureKeepsChangeForRetry(_ remove: Bool) throws {
    let container = try makeContainer()
    let context = ModelContext(container)
    let product = try makeSavedProduct(in: context)
    var state = ProductFormState(product: product)
    state.draft.name = " 編集後 "
    let image = try ProductPhotoPickerTests.imageData()
    let request = state.photo.beginLoading()
    state.photo.complete(.success(image), request: request)
    if remove {
        state.photo.remove()
    }
    let expected = remove ? nil : image
    let failing = ProductActions(context: context) { _ in .failure(StoreError.unavailable) }

    let result = state.save(using: failing) { _ in Issue.record("保存失敗を成功として通知した") }

    guard case .failure(.persistence) = result else {
        Issue.record("保存失敗が返されなかった")
        return
    }
    #expect(state.savedProductID == nil)
    #expect(state.draft.name == " 編集後 ")
    #expect(state.image == expected)
    #expect(product.image == Data([1, 2, 3]))
    #expect(!context.hasChanges)
    let before = try #require(ModelContext(container).fetch(FetchDescriptor<Product>()).first)
    #expect(before.image == Data([1, 2, 3]))

    try state.save(using: ProductActions(context: context)) { _ in }.get()

    let saved = try #require(ModelContext(container).fetch(FetchDescriptor<Product>()).first)
    #expect(saved.id == product.id)
    #expect(saved.name == "編集後")
    #expect(saved.image == expected)
    #expect(state.error == nil)
}
